// 集約 AGG-1 の CMD-1
"preconditions": [
  { "id": "PRE-1", "condition": { "target": "ST-2", "op": "eq", "value": "TERM-10" }, "reject": "TERM-12",
    "example": { "given": { "ST-2": "TERM-11", "ST-3": { "count": 2 } },
                  "when":  { "args": { "ARG-1": "12:30" } } } },
  { "id": "PRE-2", "condition": { "target": "ST-3", "agg": "count", "op": "ge", "value": 1 }, "reject": "TERM-13",
    "example": { "given": { "ST-2": "TERM-10", "ST-3": { "count": 0 } },
                  "when":  { "args": { "ARG-1": "12:30" } } } }
],
"accept_examples": [
  { "id": "OK-1",
    "given": { "ST-2": "TERM-10", "ST-3": { "count": 2 } },
    "when":  { "args": { "ARG-1": "12:30" } },
    "then":  { "state": { "ST-2": "TERM-11" }, "emits": ["EVT-1"] } }
]
// ST-4 = ARG-1 は POST-2 から、EVT-1 の欄の値は fields[].from から道具が導く

// 集約 AGG-1 の不変条件
{ "id": "INV-2", "condition": { ... },
  "violation": { "state": { "ST-2": "TERM-11", "ST-3": { "count": 0 } },
                 "via": "CMD-1.PRE-2" } }   // 拒否の例の入力を使う

// 値オブジェクト VO-1
{ "id": "INV-2", "condition": { "target": "CMP-1", "op": "le", "value": 99 },
  "impossible": { "CMP-1": 100 } }

// ドメイン DOM-1
"quality": [
  { "id": "QR-1", "name": "確定の応答",
    "characteristic": "性能効率性",
    "target": "応答時間",
    "agg": { "kind": "percentile", "p": 95 },
    "op": "le", "value": 2, "unit": "秒",
    "preconditions": [ { "target": "同時に処理する注文の数", "op": "eq", "value": 50 } ],
    "environment": "本番相当" }
],
"success_criteria": [
  { "id": "SC-1", "name": "約束どおりに渡せる",
    "preconditions": [ { "target": "注文の状態", "op": "eq", "value": "TERM-11" } ],
    "target": "受け取り予定時刻と渡した時刻の差",
    "agg": "ratio", "range": { "op": "le", "value": 5, "unit": "分" },
    "op": "ge", "value": 95, "unit": "%",
    "window": "1か月",
    "source": { "events": ["TERM-7", "（受け渡しの業務イベント：宣言に無い）"] } },
  { "id": "SC-2", "name": "列が短い", ..., "source": "システムの外" }
]

// テスト実装の報告（前回の必須5欄に、任意の欄 measured を足す）
{ "condition": "UC-1.STEP-5.QR-1", "hash": "…", "test": "…", "level": "system", "result": "pass",
  "measured": { "value": 1.4, "unit": "秒" } }
